                    uint16_t nation_ptr = DG16(0x5398u);
                    uint8_t cl = DG8((uint16_t)(nation_ptr + 0x10000u - 0x6e84u));
                    uint8_t our_val = DG8((uint16_t)((uint16_t)nation_idx + 0x10000u - 0x6e84u));
