/* ----------------------------------------------------------------------------
 * colony_screen_enter -- VICEROY colony ENTRY  (file 0x025EB6 .. 0x025EED).
 * ----------------------------------------------------------------------------
 * Loads the COLONY.PIK background then enters the generic screen-view dispatcher
 * with the colony screen-id.  enter_screen_view internally routes screen-id 0x2C
 * to the colony paint composer func_028592.
 *
 *   0x025EC6  push 1                                  ; load-PIK arg
 *   0x025EC8  push 0x0BA0                             ; "COLONY" PIK string id
 *   0x025ECB  lcall 0x191F:0x087A                     ; load_PIK(handle args.., 0x0BA0)
 *   0x025ED3  or ax,ax; je 0x12FD                     ; bail if load failed
 *   0x025EDF  mov ax,0xFFAD; mov dx,2                 ; view params
 *   0x025EE5  mov bx,0x2C                             ; screen-id 0x2C  (COLONY)
 *   0x025EE8  lcall 0x181F:0x0772                     ; enter_screen_view(0x2C)
 *   0x025EED  retf
 * ---------------------------------------------------------------------------- */
void colony_screen_enter(void)
{
    /* load COLONY.PIK background.  @asm 0x025EC8 push 0x0BA0 / 0x025ECB lcall 0x191F:0x087A */
    /* (5 sheet-handle words [0x839E..0x83A4] + flag 1 pushed at 0x025EB6..0x025EC4) */

    /* enter the colony screen view.  @asm 0x025EE5 mov bx,0x2C / 0x025EE8 lcall 0x181F:0x0772 */
    enter_screen_view(0x2C);                           /* screen-id 0x2C -> func_028592 */
}

/* ----------------------------------------------------------------------------
 * colony_paint_stockpile -- VICEROY func_0281D6  (file 0x0281D6, page record-1).
 * ----------------------------------------------------------------------------
 * The 16-commodity stockpile bar across the screen bottom (y=179..199).  recol
 * twin = func_019622.  Two 16-iteration loops: the first lays each commodity
 * icon + quantity text; the second overlays the selected/boycott highlight.
 *
 *   0x0281DB  push 0x15,0x140,0xB3,0; call 0x7ED3        ; bar bg fill (0,179,320,21)
 *   0x0281EC  mov [bp-0x6E],1                            ; first cell X = 1
 *   0x0281F1  mov [bp-0x72],0xB5                         ; icon Y base = 181
 *   0x0281F6  mov [bp-0x7E],0                            ; i = 0
 *   loop i=0..15 (cmp [bp-0x7E],0x10 @ 0x028231):
 *     0x028253  add ax,0x17                              ; sprite id = i + 23
 *     0x02825D  cx = ICONS_hdr[+0x152 + i*12]; sar 1     ; half sprite width
 *     0x028266  dx = X - cx + 9                          ; centered draw X
 *     0x028270  lcall 0x181F:0x254                       ; blit_sprite(&0x2DA8,id,dx,y)
 *     0x02822A  add [bp-0x6E],0x13                       ; X += 19
 *   highlight loop i=0..15 (cmp [bp-0x7E],0x10 @ 0x0283EB):
 *     0x028399  al = [0x33A] (selected good); 0x0283BB push 0x0E (highlight)
 *   0x0283F1  push 0xF,0xB3,0x132; gold=[0x2F5E]; draw   ; gold at x=306,y=179
 *   0x028415  if [bp+6]!=0: lcall 0x181F:0xE2            ; re-blit bar band
 * ---------------------------------------------------------------------------- */
void colony_paint_stockpile(int repaint)
{
    int i;
    int x      = 1;        /* [bp-0x6E]  @asm 0x0281EC mov [bp-0x6E],1 */
    int y_icon = 0xB5;     /* [bp-0x72]  @asm 0x0281F1 mov [bp-0x72],0xB5 (181) */

    /* bar background fill (x=0,y=179,w=320,h=21).
     * @asm 0x0281DB push 0x15,0x140,0xB3,0 / 0x0281E6 call 0x7ED3. */
    fill_rect(0, 0xB3, 0x140, 0x15);                   /* @asm 0x0281DB..0x0281E6 */

    /* === pass 1: 16 commodity cells, pitch 19, sprite base 22 (ICONS.SS) === */
    for (i = 0; i < 0x10; i++) {                       /* @asm 0x028231 cmp [bp-0x7E],0x10 */
        /* The assembly annotation @0x028253 says "add ax,0x17" (sprite_id=i+23), but
         * the actual ICONS.SS has frame 22=Food, frame 23=Sugar (verified visually).
         * The annotation assumed the frame at index 23 = Food, but the MADSPACK SS
         * stores frames 0-based and Food is at frame 22 (0x16), not 23 (0x17).
         * Fix: use i + 0x16 so i=0 blits frame 22 (Food) first. */
        int sprite_id = i + 0x16;                      /* Food=22, Sugar=23, ..., Muskets=37 */
        int qty       = ctx ? (int)ctx->stockpile_9a[i] /* colony +0x9A + i*2 */
                            : 0;                       /* @asm 0x028288 [bx+si+0x9A] */
        /* center on cell X using ICONS header width:
         *   half_w = ICONS_hdr[+0x152 + i*12] >> 1   (@asm 0x02825D / 0x028262)
         *   draw_x = x - half_w + 9                   (@asm 0x028264 / 0x028266) */
        {
            int half_w = sheet_frame_w_icons(sprite_id) >> 1;  /* @asm 0x02825D sar 1 */
            int draw_x = x - half_w + 9;                       /* @asm 0x028266 */
            /* blit_sprite(&0x2DA8 = ICONS.SS desc, sprite_id, draw_x, y_icon).
             * @asm 0x028270 lcall 0x181F:0x254. */
            blit_sprite(/*&0x2DA8*/ 0, sprite_id, draw_x, y_icon);  /* @asm 0x028270 */
            /* P2: quantity text under the icon (@asm 0x028288 reads rec[+0x9A+i*2],
             * 0x0311AE sprintf+draw on the Europe twin).  Centre a small number in
             * the 19px cell, baseline near the cell bottom (y~194). */
            {   char q[8];
                int qw, qx;
                snprintf(q, sizeof q, "%d", qty);
                qw = vid_text_width(q);
                qx = x + 9 - (qw >> 1);
                vid_text_color(ui_color_for(0xFF, 0xFF, 0xFF));  /* white qty */
                vid_text_xy(q, qx, 0xC1);                        /* y=193 cell bottom */
            }
        }
        x += 0x13;                                     /* @asm 0x02822A add [bp-0x6E],0x13 (pitch 19) */
    }

    /* === pass 2: selected-good / boycott highlight, 16 cells === */
    for (i = 0; i < 0x10; i++) {                       /* @asm 0x0283EB cmp [bp-0x7E],0x10 */
        if (i == g_hilite_good_33A) {                  /* @asm 0x02839E cmp ax,[bp-0x7E] (al=[0x33A]) */
            ;                                          /* highlight color 0x0E  @asm 0x0283BB push 0x0E */
        }
    }

    /* gold display at (x=306, y=179, w=15), value = [0x2F5E].
     * @asm 0x0283F1 push 0xF,0xB3,0x132 / 0x0283F9 push [0x2F5E] / fmt + draw_text. */
    (void)g_gold_2F5E;                                 /* @asm 0x0283F9 push [0x2F5E] */

    /* re-blit the stockpile band on repaint.  @asm 0x02840F cmp [bp+6],0 /
     * 0x028415 push 0xB3,0x140,0x15 / 0x028424 lcall 0x181F:0xE2. */
    if (repaint != 0) {                                /* @asm 0x02840F cmp [bp+6],0 */
        blit_band(0, 0xB3, 0x140, 0x15);               /* @asm 0x028415..0x028424 (0,179,320,21) */
    }
}

/* ----------------------------------------------------------------------------
 * colony_paint_buildings -- VICEROY func_02701C  (file 0x02701C, page record-1).
 * ----------------------------------------------------------------------------
 * The 15 building slots (recol twin = func_018475).  Per-slot (x,y) come from a
 * DGROUP table; per-slot TYPE and LEVEL bytes select the sprite / empty lot.
 *
 *   0x027031  push 0x80,0,..; lcall 0x181F:0xCE          ; top-band backdrop
 *   0x027044  push 7,0x78,0xC7,8,0; lcall 0x181F:0x4FC    ; framed backdrop
 *   0x027067  mov [bp-8],0                                ; slot i = 0
 *   loop i=0..14 (cmp [bp-8],0xF @ 0x02707B):
 *     0x027087  ax = tbl[i].x = [bx+0x266]; cx = tbl[i].y = [bx+0x268]; cx += 8
 *     0x027095  dl = TYPE  = [bx-0x729E]
 *     0x02709D  al = LEVEL = [bx-0x717E]
 *     0x0270A2  if (al < 0)  call 0x7EF1                  ; empty lot
 *               else         call 0x7E33                  ; draw one building
 *   0x0270B4  if [bp+6]!=0: lcall 0x181F:0xE2             ; re-blit backdrop
 * ---------------------------------------------------------------------------- */
/* BUILDING.SS, lazily loaded (48 building sprites). The draw leaf func_026DD4
 * (reached via the 0x7E33 trampoline -> 0x191F:0x66C -> overlay seg2:0x14D4)
 * blits BUILDING.SS frame = LEVEL+1 at the slot (x,y) -- see the decode in
 * docs/RENDER_GROUNDTRUTH.md.  Blitted directly (BUILDING.SS shares the master
 * VICEROY.PAL, so its indices are correct under the colony screen palette). */
static ss_sheet_t col_bldg;
static int        col_bldg_state;          /* 0=unloaded 1=ok -1=failed */

static int col_bldg_ready(void)
{
    if (col_bldg_state == 0) {
        char path[512];
        extern const char *viceroy_data_dir(void);
        const char *dir = viceroy_data_dir();
        size_t n = strlen(dir);
        if (n > sizeof path - 16) n = sizeof path - 16;
        memcpy(path, dir, n);
        memcpy(path + n, "/BUILDING.SS", 13);          /* incl NUL */
        col_bldg_state = (ss_load(path, &col_bldg) == 0 && col_bldg.nframes > 0)
                             ? 1 : -1;
    }
    return col_bldg_state == 1;
}

/* func_026DD4 base-frame select: frame = LEVEL+1, with the wall special-cases
 * (@asm 0x026E00..0x026E39). q9fc(t) = "colony has building tier t"; modelled
 * here against the per-slot LEVEL bytes the setup already resolved.
 *
 * INDEXING NOTE: the original blit_sprite (0x181F:0x254 / func_00E76A) uses
 * 1-based sprite IDs: sprite #1 = BUILDING.SS frame[0], sprite #48 = frame[47].
 * The special-case values 0x2F (47) and 0x30 (48) are 1-based — both valid for a
 * 48-frame sheet.  The modern ss_blit is 0-based, so:
 *   ss_blit frame = (original 1-based id) - 1 = (LEVEL+1) - 1 = LEVEL.
 * Wall special cases also shift by -1: 0x11→0x10, 0x2F→0x2E, 0x30→0x2F. */
static int col_bldg_frame(int level)
{
    /* base: original 1-based frame = LEVEL+1  (@asm 0x026DE5 [bp-0x58]=[bp+6]+1)
     * convert to 0-based for ss_blit: subtract 1 → result = LEVEL. */
    int frame = level;                      /* 0-based ss_blit index */
    /* wall-tier special cases (@asm 0x026E05..0x026E39), converted to 0-based:
     *   original 0x11 (17, 1-based) → 0x10 (16, 0-based)
     *   original 0x2F (47, 1-based) → 0x2E (46, 0-based) = Fort sprite
     *   original 0x30 (48, 1-based) → 0x2F (47, 0-based) = Fortress sprite */
    return frame;
}

void colony_paint_buildings(int repaint)
{
    int i;

    /* top-band backdrop fill + frame (region around y=7..8, w=199).
     * @asm 0x027031 lcall 0x181F:0xCE  -> 1px outer frame (0,7)-(199,?)
     * @asm 0x027044 lcall 0x181F:0x4FC -> framed weave fill (0,8,199,120):
     *   the 0x4FC leaf tiles the 0x93F0 texture block, which is the PARCH.SS
     *   sandy-parchment weave (master indices 98..110).  This is the sandy
     *   building plot the buildings sit on (ref_colony_interior.png). */
    draw_box(0, 7, 199, 128, 0);                       /* @asm 0x027031 outer frame, colour 0 */
    tile_texture(TEX_PARCH, 0, 8, 199, 120);           /* @asm 0x027044 sandy plot (0,8,199,120) */

    /* === 15 building slots === */
    for (i = 0; i < 0x0F; i++) {                       /* @asm 0x02707B cmp [bp-8],0xF */
        int bx_x  = DGS16(0x0266 + i*4);              /* tbl[i].x  [bx+0x266] @asm 0x027087 */
        int bx_y  = DGS16(0x0268 + i*4) + 8;          /* tbl[i].y  [bx+0x268]+8 @asm 0x02708B/0x02708F */
        int btype = DGS8 (0x8D62 + i);                /* TYPE  [bx-0x729E] @asm 0x027095 */
        int blvl  = DGS8 (0x8E82 + i);                /* LEVEL [bx-0x717E] @asm 0x02709D */
        (void)btype;

        if (blvl < 0) {                                /* @asm 0x0270A2 or ax,ax; jl */
            ;                                          /* empty lot: @asm 0x027072 call 0x7EF1 */
        } else if (col_bldg_ready()) {                 /* building: func_026DD4 (0x7E33) */
            int frame = col_bldg_frame(blvl);
            /* Some building LINES (e.g. line 3 = @BUILDING 9,10,11; line 5 =
             * 15,16,17) have BLANK top-tier frames (1x1 placeholders 10,11,17,
             * 30,31) in BUILDING.SS: those tiers reuse the line's base sprite
             * (the structure looks the same when upgraded).  frame = good_index
             * lands on the blank, drawing nothing -- walk DOWN to the nearest
             * non-blank frame of the same line (the blanks are always the top
             * tiers, so the lower frame belongs to the same column). */
            while (frame > 0 && frame < col_bldg.nframes &&
                   col_bldg.frames[frame].w <= 2 &&
                   col_bldg.frames[frame].h <= 2)
                frame--;
            if (frame >= 0 && frame < col_bldg.nframes)
                ss_blit_remap(&col_bldg, frame, bx_x, bx_y); /* @asm 0x026E4E lcall 0x181F:0x254 */
        }
    }

    /* re-blit backdrop on repaint.  @asm 0x0270B4 cmp [bp+6],0 /
     * 0x0270BA push 8,0xC7,0x78 / 0x0270C8 lcall 0x181F:0xE2. */
    if (repaint != 0) {                                /* @asm 0x0270B4 cmp [bp+6],0 */
        blit_band(0, 8, 0xC7, 8);                      /* @asm 0x0270BA..0x0270C8 (top backdrop band) */
    }
}

