/* ----------------------------------------------------------------------------
 * colony_paint_sol_panel -- VICEROY func_02814C  (file 0x02814C, page record-1).
 * ----------------------------------------------------------------------------
 * The panel right of the minimap (recol twin = func_019599).  Its contents are
 * chosen by mode word [0x337]: Sons-of-Liberty %, ship-in-port, or message.
 *
 *   0x02814F  push 0x30,0x5B,0x82,0xD3; call 0x7ED3       ; fill (211,130,91,48)
 *   0x02815F  al = [0x337]                                ; mode 0/1/2
 *     0 -> call 0x7DC0   ; Sons of Liberty %
 *     1 -> call 0x7E60   ; ship in port
 *     2 -> call 0x7EB0   ; active message
 *   0x028182  if [bp+6]!=0: lcall 0x181F:0xE2             ; re-blit panel
 * ---------------------------------------------------------------------------- */
void colony_paint_sol_panel(int repaint)
{
    /* region fill (x=211, y=130, w=91, h=48).
     * @asm 0x02814F push 0x30,0x5B,0x82,0xD3 / 0x02815A call 0x7ED3. */
    fill_rect(0xD3, 0x82, 0x5B, 0x30);                 /* @asm 0x02814F..0x02815A (211,130,91,48) */

    /* mode dispatch on [0x337].  @asm 0x02815F mov al,[0x337].
     * The panel content centres in the (211,130,91,48) region; the text draws
     * over the COLONY.PIK landscape (the fill leaf is a no-op).  Cream text. */
    {   int cx = 0xD3 + 0x5B/2;                        /* panel centre x = 256 */
        int cream = ui_color_for(0xF0, 0xE0, 0xB0);
        vid_text_color(cream);
        switch (g_panel_mode_337) {                    /* @asm 0x02815F / jump table 0x028178 */
            case 1: {                                  /* ship in port  @asm 0x02816D 0x7E60 */
                const char *s = "No Ships In Port";
                int tw = vid_text_width(s);
                vid_text_xy(s, cx - tw/2, 0x8C);       /* y=140 */
                break;
            }
            case 2:  break;                            /* message:  @asm 0x028173 call 0x7EB0 */
            case 0:  default: {                        /* SoL %:    @asm 0x028167 call 0x7DC0 */
                /* Sons of Liberty membership header (the % bars are a leaf). */
                const char *s = "Sons of Liberty";
                int tw = vid_text_width(s);
                vid_text_xy(s, cx - tw/2, 0x86);       /* y=134 */
                break;
            }
        }
    }

    /* re-blit panel on repaint.  @asm 0x028182 cmp [bp+6],0 /
     * 0x028188 push 0x82,0x5B,0x30 / 0x028197 lcall 0x181F:0xE2. */
    if (repaint != 0) {                                /* @asm 0x028182 cmp [bp+6],0 */
        blit_band(0xD3, 0x82, 0x5B, 0x30);             /* @asm 0x028188..0x028197 (211,130,91,48) */
    }
}

/* ----------------------------------------------------------------------------
 * colony_paint_title -- VICEROY func_0268CE  (file 0x0268CE, page record-1).
 * ----------------------------------------------------------------------------
 * The colony name / population title text (recol twin = func_017D31).  Hidden
 * while the colony status byte is >= 4, or when its status-table gate is set.
 *
 *   0x0268D3  bx = [0x8542]
 *   0x0268D7  if [bx+0x1A] >= 4: return                   ; status hidden
 *   0x0268E2  imul bx,status,0x34; if [bx+0x543F]==0 ...   ; status-table gate
 *   0x0268EE  if [0xB98]!=0 or [0x828]!=0: return          ; minimized / blocked
 *   0x02690A  al = [bx+0x1B]                               ; owner / color
 *   (name + "Pop:" assembled by fmt/strcat leaves, printed by generic printer)
 * ---------------------------------------------------------------------------- */
void colony_paint_title(void)
{
    char buf[80];
    uint16_t rec;
    uint8_t  pw;
    const char *name, *season;
    int year, gold, tw, tx;

    /* T0: gates — status/owner byte (≥4 hides), nation-active, minimized, blocked.
     *   @asm 0x0268D3 bx=[0x8542]
     *   @asm 0x0268D7 cmp [bx+0x1A],4; jae return
     *   @asm 0x0268E2 imul bx,[bx+0x1A],0x34; cmp [bx+0x543F],0; je return
     *   @asm 0x0268EE cmp [0xB98],0 / 0x0268F8 cmp [0x828],0; jne return */
    rec = DG16(0x8542);
    pw  = DG8(rec + 0x1A);                            /* owner power (≥4 = hidden) */
    if (pw >= 4) return;
    if (!DG8((uint16_t)((uint16_t)pw * 0x34u + 0x543Fu))) return; /* nation-active gate */
    if (DG16(0xB98) != 0 || DG16(0x828) != 0) return; /* minimized / blocked */

    /* T1-T5: assemble "<name>, <season> <year>, Gold: <gold>"
     *   @asm 0x026930 rec+2 = name  (16-byte null-terminated field)
     *   @asm 0x026965 [0x9800+[0x538C]*2] = season string handle
     *         (spec annotation 0x97C0 was incorrect; SEASONS is at 0x9800 per loader)
     *   @asm 0x026a44 [0x538A] = year
     *   @asm 0x026a61 [0x2F5E] = gold */
    name   = (const char *)&DG8(rec + 2);
    { uint16_t si = DG16(0x538C) & 1u;
      season = viceroy_str(DG16((uint16_t)(0x9800u + si * 2u))); }
    year = (int)(int16_t)DG16(0x538A);
    gold = (int)(int16_t)DG16(0x2F5E);

    buf[0] = 0;
    if (name && name[0]) { strncat(buf, name, 16); buf[sizeof buf - 1] = 0; }
    strcat(buf, ", ");
    if (season && season[0]) strcat(buf, season);
    strcat(buf, " ");
    { char t[12]; int n = year; int k = (int)(sizeof buf - 1 - (int)strlen(buf));
      if (k > 0) { snprintf(t, sizeof t, "%d", n); strncat(buf, t, (size_t)k); } }
    strncat(buf, ", Gold: ", sizeof buf - 1 - strlen(buf));
    { char t[12]; int n = gold; int k = (int)(sizeof buf - 1 - (int)strlen(buf));
      if (k > 0) { snprintf(t, sizeof t, "%d", n); strncat(buf, t, (size_t)k); } }
    buf[sizeof buf - 1] = 0;

    /* T6: TEXT centered in full width at y=1, UI green #528A31.
     *   @asm 0x026aa6 printer 0x181F:0xB0 (centers + draws in green) */
    tw = vid_text_width(buf);
    tx = (320 - tw) / 2;
    if (tx < 0) tx = 0;
    vid_text_color(ui_color_for(0x52, 0x8A, 0x31));   /* UI green #528A31 */
    vid_text_xy(buf, tx, 1);
}

