/* europe_draw_stockpile -- 16-commodity strip at screen bottom.
 * func_0310B4  @file 0x0310B4
 *
 * Background fill (0,179,320,21); 16 icon+price cells; gold footer.
 * Cell x = 1 + i*19  (pitch 0x13); icon y = 0xB5 (181); price y = 0xC2 (194).
 * ICONS.SS frame = i + 0x16 (Food=22 .. Muskets=37, 0-based MADSPACK order).
 * Gold footer: x=0x132(306), y=0xB3(179), value DG16(0x2F5E). */
void europe_draw_stockpile(int blit)
{
    char pstr[16];
    int  i, x = 1;

    vid_box_fill(0, 0xB3, 0x140, 0x15, 0);  /* bg (x=0,y=179,w=320,h=21) @asm 0x0310B9 */

    for (i = 0; i < 0x10; i++) {            /* @asm 0x031253 CMP [bp-0x72],0x10 */
        int sid   = i + 0x16;               /* Food=22 .. @asm ADD ax,0x17 (1-based->0-based) */
        int hw    = sheet_frame_w_icons(sid) >> 1;
        int dx    = x - hw + 9;             /* centre in cell  @asm 0x028266 twin */

        blit_sprite(0, sid, dx, 0xB5);      /* icon y=181  @asm 0x0310CF [bp-0x6a]=0xB5 */

        /* bid/ask price text at y=194 (@asm 0x0310CF [bp-0x6a=0xC2] twin) */
        snprintf(pstr, sizeof pstr, "%d", market_bid_price(i));
        vid_text_color(0x0F);
        vid_text_xy(pstr, x + 9 - (vid_text_width(pstr) >> 1), 0xC2);

        x += 0x13;  /* pitch 19px  @asm 0x03124C ADD [bp-0x68],0x13 */
    }

    /* gold footer x=0x132(306), y=0xB3(179)  @asm 0x03125C push 0xF,0xB3,0x132,[0x2f5e] */
    {
        char gstr[24];
        snprintf(gstr, sizeof gstr, "$%d", (int)(int16_t)DG16(0x2F5E));
        vid_text_color(0x0F);
        vid_text_xy(gstr, 0x132, 0xB3);
    }
    (void)blit;
}

/* europe_draw_title -- nation/year/tax banner in the top strip (y=0..45).
 * func_030F76  @file 0x030F76
 *
 * Reads active power index from DG16(0x9E12), PowerRecord base at 0x8808 +
 * power*0x13C, year from DG16(0x538A), tax% from PowerRecord[+0x01].
 * Font: FONTTINY via vid_text_xy; text centered at y=4.
 * @asm  0x030F7A MOV bx,[0x9E12]; 0x031007 [0x538A]; 0x03103F [0x84FC]+1. */
void europe_draw_title(int blit)
{
    static const char *nations[4] = { "English", "French", "Spanish", "Dutch" };
    char hdr[96];
    int  power = (int)(int16_t)DG16(0x9E12);         /* @asm 0x030F7A MOV bx,[0x9E12] */
    int  year  = (int)(int16_t)DG16(0x538A);          /* @asm 0x031007 */
    int  pr_lo = (int)(0x8808 + (unsigned)power * 0x13C);  /* PowerRecord base */
    int  tax   = (int)DG8((uint16_t)(pr_lo + 0x01));  /* @asm 0x03103F */
    int  tw;

    if (power < 0 || power > 3) power = 0;
    snprintf(hdr, sizeof hdr, "%s Port  %d  Tax %d%%",
             nations[power], year, tax);
    tw = vid_text_width(hdr);
    vid_text_color(ui_color_for(0x52, 0x8A, 0x31));  /* UI green */
    vid_text_xy(hdr, (320 - tw) >> 1, 4);
    (void)blit;
}

/* europe_draw_dock_ships -- dock scene + 6 ship slots at anchor.
 * func_0314DC  @file 0x0314DC
 *
 * Dock scene fill (143,118,81,60)  @asm 0x0314E1 PUSH 0x3C,0x51,0x76,0x8F.
 * In-port row layer (143,81,120,69) @asm 0x0314F8.
 * 6 ship slots, ICONS.SS frame 0x7B (123) @asm 0x03154F MOV ax,0x7B.
 * Per-slot (x,y,w) via cs:0x6D55 (unresolved); approximated as 120/6=20px pitch. */
void europe_draw_dock_ships(int blit)
{
    int i, sx;

    /* dock scene fill (x=0x8F=143, y=0x76=118, w=0x51=81, h=0x3C=60) */
    vid_box_fill(0x8F, 0x76, 0x51, 0x3C, 0);   /* @asm 0x0314E1 */

    /* in-port ship row layer (x=143, y=81, w=120, h=69) */
    vid_box_fill(0x8F, 0x51, 0x78, 0x45, 0);   /* @asm 0x0314F8 */

    /* 6 ship slots with ICONS.SS frame 0x7B (123)
     * @asm 0x031521 CMP [bp-0x5c],6;  0x03154F MOV ax,0x7B */
    sx = 0x8F;                               /* start x = dock scene left */
    for (i = 0; i < 6; i++) {
        int hw = sheet_frame_w_icons(0x7B) >> 1;
        blit_sprite(0, 0x7B, sx + 10 - hw, 0x76 + 4);  /* y ≈ 122 in dock area */
        sx += 0x78 / 6;                      /* pitch = 120/6 = 20px */
    }
    (void)blit;
}

/* europe_draw_recruit_pool -- 3 recruit/purchase/train slots (right column).
 * func_031DC8  @file 0x031DC8
 *
 * Pool bg fill (281,89,37,32)  @asm 0x031DCC PUSH 0x20,0x25,0x59,0x119.
 * 3 cells stacking vertically; y advances by cell_h+2 per slot
 * @asm 0x031E23 INC ax;INC ax;ADD [bp-4],ax.
 * Per-slot labels: RECRUIT / PURCHASE / TRAIN from LABELS.TXT @EUROLABEL[0..2]
 * (handle 0x22D4).  @asm func_031BE6 draws each button bevel. */
void europe_draw_recruit_pool(int blit)
{
    static const char *lbls[3] = { "RECRUIT", "PURCHASE", "TRAIN" };
    int  i, cy = 0x59;                       /* y=89 @asm 0x031DDC */
    int  cell_h = (0x20 - 4) / 3;           /* ~9px; (32-4gaps)/3 cells */

    /* pool background fill (x=281, y=89, w=37, h=32) */
    vid_box_fill(0x119, 0x59, 0x25, 0x20, 0);  /* @asm 0x031DCC */

    for (i = 0; i < 3; i++) {               /* @asm 0x031E2B CMP [bp-6],3 */
        int tw;
        /* raised-bevel outline: light edge 0x30, dark edge 0x39 */
        vid_box_outline(0x119, cy, 0x25, cell_h, 0x39);  /* @asm 0x031C8A raised */
        /* label text centered inside cell */
        tw = vid_text_width(lbls[i]);
        vid_text_color(0x0F);
        vid_text_xy(lbls[i], 0x119 + (0x25 - tw) / 2, cy + 1);
        cy += cell_h + 2;                   /* @asm 0x031E23 INC ax;INC ax;ADD */
    }
    (void)blit;
}

/* ----------------------------------------------------------------------------
 * europe_screen_render -- the Europe trade-port paint composer.
 *
 * @asm_function  (top-level paint) @file 0x031E4C  (second entry in the disasm
 *                block listed as func_031DC8; page_04.asm offset 0x235C).
 * @asm_disasm    code/VICEROY/disasm_overlay_reseg/page_04.asm
 *
 * Structural twin of colony paint_colony_screen (func_0199D8,
 * docs/COLONY_RENDERER_DECODED.md §1).  Fills the play area, then calls the
 * element sub-renderers in fixed order, then draws the outer frame.
 * The "blit" arg is 0 here (compose into the back buffer; the caller blits).
 * ---------------------------------------------------------------------------- */
void europe_screen_render(void)
{
    /* (0) clear the play area below the title strip; EUROPE.PIK (loaded by
     * europe_open via 0x191F:0x87A key 0x0FBA) shows through where not drawn.
     * @asm 0x031E4C-56  PUSH 0xC0,0x140,8,0 -> fill_rect(x=0,y=8,w=320,h=192). */
    fill_rect(0, 8, 320, 192);          /* @asm 0x031E4C..0x031E56 cs:0x6DDC */
    ov_prep_clip();                     /* @asm 0x031E5E near CALL cs:0x6DB4 */

    /* (1) 16-commodity stockpile strip at y=179, stride 19, ICONS+23. */
    europe_draw_stockpile(0);           /* @asm 0x031E63 CALL 0x15C4 (func_0310B4) */

    /* (2) "Selling <Good> at <N> Gold: (<gold>)" banner. */
    europe_draw_title(0);               /* @asm 0x031E6B CALL 0x1486 (func_030F76) */

    /* (3) dock scene + ships at anchor + in-port unit list. */
    europe_draw_dock_ships(0);          /* @asm 0x031E73 CALL 0x19EC (func_0314DC) */

    ov_draw_extra_a(0);                 /* @asm 0x031E7C near CALL cs:0x6D73 */
    ov_draw_extra_b(0);                 /* @asm 0x031E85 near CALL cs:0x6E36 */

    /* (4) recruit / immigration pool (3 candidate slots, right column). */
    europe_draw_recruit_pool(0);        /* @asm 0x031E8D CALL 0x22D8 (func_031DC8) */

    /* (5) outer screen frame.  @asm 0x031E95-A0 PUSH 0,0x140,0xC8,0 ; ax=dx=bx=0;
     * LCALL 0x181F:0xE2 -> box_frame(x=0,y=0,w=320,h=200,c=0). */
    box_frame(0, 0, 320, 200, 0);       /* @asm 0x031EA0 LCALL 0x181F:0x00E2 */
}

/* ============================================================================
 * europe_open -- VICEROY func_030DBC  (the "go to Europe" command entry)
 * ----------------------------------------------------------------------------
 * STATUS: BYTE_VERIFIED structure + corrected thunk identities (2026-05-30).
 *
 * @asm_function  func_030DBC   file 0x030DBC..0x030DF3
 * @asm_disasm    code/VICEROY/disasm_overlay_reseg/page_04.asm
 *
 * This is the Europe SCREEN-ENTRY stub (not the composer): it loads the
 * EUROPE.PIK backdrop, then enters the interactive Europe view (which paints
 * via europe_screen_render above and runs the input loop).  Its exact twin is
 * the COLONY entry stub at @asm 0x025EC8 (key 0x0BA0="COLONY", screen_id 0x2C).
 *
 * Purpose proven by STRING XREF:
 *   @asm 0x030DCE  PUSH 0x0FBA   -> GAME.TXT key "EUROPE"  (@file 0x1E95A)
 *
 * Behaviour, byte-faithful:
 *   overlay_call_191F_087A(0xfba, (int16_t)DG16(0x839e), (int16_t)DG16(0x83a0), (int16_t)DG16(0x83a2), (int16_t)DG16(0x83a4), 0)             (@asm 0x030DD1 0x191F:0x87A)
 *   if (handle != 0)                                      (@asm 0x030DDB OR ax,ax / JE)
 *       enter_screen_view(0,0,0,0, ax=0xFFAD, dx=2, bx=0x2B)  (@asm 0x030DEE 0x181F:0x772)
 *
 * NOTE (correction): the prior revision labelled 0x191F:0x87A as
 * "menu_dispatch_region" -- that was wrong.  0x191F:0x87A is load_PIK
 * (load named .PIK by GAME.TXT key into the rect); verified by the identical
 * call pattern at the COLONY stub and the WOODPANL report panel (@asm
 * 0x039E70).  And 0x181F:0x772 is enter_screen_view (screen_id 0x2B = Europe),
 * not "ov_enter_view of unknown meaning": the 0xFFAD/2 sentinel pair appears at
 * exactly the two screen-entry stubs (Europe 0x2B, Colony 0x2C).
 * ============================================================================ */
#define KEY_EUROPE     0x0FBA   /* "EUROPE"   @asm 0x030DCE / @file 0x1E95A */
#define SCREEN_ID_EUR   0x2B     /* Europe view id @asm 0x030DEB (0x2C = Colony) */
#define SCREEN_EUROPE   SCREEN_ID_EUR

extern int16_t g_dialog_rect[4];   /* DGROUP:0x839E (x), 0x83A0 (y), 0x83A2, 0x83A4 */
extern int  load_PIK(int z0, int x0, int y0, int x1, int y1,
                     int key);                  /* 0x191F:0x87A */
extern void enter_screen_view(int z0, int z1, int z2, int z3,
                              int ax, int dx, int bx);   /* 0x181F:0x772 */

void europe_open(void)
{
    int handle = load_PIK(0,
                          g_dialog_rect[0], g_dialog_rect[1],
                          g_dialog_rect[2], g_dialog_rect[3],
                          KEY_EUROPE);            /* @asm 0x030DD1 0x191F:0x87A */
    if (handle != 0) {                            /* @asm 0x030DDB OR ax,ax / JE 0x1303 */
        /* enter the Europe view; the paint pass is europe_screen_render().
         * @asm 0x030DE5..0x030DEE  ax=0xFFAD, dx=2, bx=0x2B (Europe screen id). */
        enter_screen_view(0, 0, 0, 0, 0xFFAD, 2, SCREEN_ID_EUR); /* @asm 0x030DEE 0x181F:0x772 */
    }
    /* @asm 0x030DF3 RETF */
}

