void ov_panel_geom_init(void)
{
    near_6DDC(0, 8, 0x140, 0x50);   /* @asm 0x0324B6..0x0324C0 */
    G16(0xFC8) = 0xC;               /* @asm 0x0324C6 MOV word [0xFC8],0x0C */
}

