    /* @asm 03C53D..03C546 PUSH 0x0B,[0x53D2],[bp+6] -> 0x181F:0xA10. */
    power_set_a10((int)arg0_power_bp_06, (int)g_self_marker_53D2, 0x0B);
    /* @asm 03C54E..03C557 PUSH 0x60,[0x5398],[bp+6] -> 0x181F:0xA06. */
