            DG8(b - 0x6B5A) = 0;       /* @0x0421CB worked map A                */
            DG8(b - 0x6B1A) = 0;       /* @0x0421CF worked map B                */
            DG8(b - 0x6ADA) = 0;       /* @0x0421D3 worked map C                */
            DG8(b - 0x6E74) = 0;       /* @0x0421D7 */
            DG8(b - 0x6A8E) = 0;       /* @0x0421DB */
            DG8(b - 0x6A4E) = 0;       /* @0x0421DF */
