    DG8(0xA89A) = 0;                   /* @0x0424C2 rebel headcount            */
    DG8(0xA89B) = 0;                   /* @0x0424C5 tory headcount             */
    DG16(0x9E54) = 0;                  /* @0x0424CA rebel point sum            */
    DG16(0x9E52) = 0;                  /* @0x0424CD tory point sum             */

