    int n;                             /* bp-0x20 row count                   */
    int i;                             /* bp-0xe                              */
    int terr;                          /* bp-0x12                             */
    int qty;                           /* bp-8                                */
    int w;                             /* bp-0xa                              */
    int base_x;                        /* bp-0x10                             */
