        overlay_call_181F_0254();      /* @0x042EC3 cargo_glyph(base_x+terr,row_x,*ypos,0x2da8) */
        /* @0x042ED1 advance *ypos by glyphHeightTable[idx*12 + 0x3e] + 1. */
        *ypos += DG16(0/*far es:[bx+si+0x3e]*/) + 1;/* @0x042EDA */
