    if (type == 5 && cargo == 0x16)    /* @0x04303C..0x043046 */
        spr = DG16(0x2DC2);            /* @0x043048 */
    if (type == 3 && cargo == 0x18)    /* @0x04304E..0x043058 */
        spr = DG16(0x2DC2);            /* @0x04305A */

