                    int rel = func_007F34_logic_sz_27(power, uu[0x03] & 0x0F);
                                                        /* @0x4CFFB 0x181F:0xA38 */
                    if ((rel & 0x60) != 0x20 &&         /* @0x4D003/0x4D005 */
                        uu[UNIT_TYPE_OFF] != 0x10)      /* @0x4D009 */
                        continue;
