                        if (uu[UNIT_TYPE_OFF] == 0x0D &&/* @0x4CE23 */
                            DG8(0x9259 + power * 0x13) > 1) {  /* @0x4CE2E */
                            uu[0x04] |= 0x20;           /* @0x4CE44 */
                            tier_done = 1;              /* @0x4CE49 */
                        }
