                        w += 1;                              /* @asm 0x06404E inc di */
                    if (t < 4 && feat == 0x19) {            /* @asm 0x064052/0x06405B */
                        mul = 5;
                        w = (w + 1) >> 1;                    /* @asm 0x064061 */
                    }
