                g_opt_104 = 1;                          /* @asm 0x070D96 */
                break;
            case 'Z':                                   /* @asm table 0x13E */
                g_opt_82B = 1;                          /* @asm 0x070D9E */
                break;
            default:                                    /* @asm table 0x186 no-op */
                break;
