    g_ref_regulars_53DA  = d * 8 + 15;   /* @asm 0x0756A2 */
    g_ref_cavalry_53DC   = (d + 1) * 5;  /* @asm 0x0756B5 */
    g_ref_artillery_53E0 = d * 6 + 2;    /* @asm 0x0756C5 */
    g_ref_manowar_53DE   = d * 3 + 2;    /* @asm 0x0756D0 */
