/* ## SOURCE: viceroy_source/src/platform/intro_render_glue.c
/* ## range: 0x40000000..
/* ##################################################################### */
/* ============================================================================
 * intro_render_glue.c -- platform renderer for the Phase-6.4 intro player.
 * ----------------------------------------------------------------------------
 * Strong overrides of intro_player.c's weak render hooks. Faithful port of
 * OPENING.EXE's player loop (decoded in docs/INTRO_FRAMELOOP_DECODE.md):
 *
 *   - backdrop = OPENING.PIK, a **960x132 voyage panorama** shown through a
 *     320-wide window that PANS across it (the scene scrolls; sprites are
 *     screen-fixed -- proven by OPENSHIP's 8 frames sharing one (x,y)).
 *     OPENBORD.PIK frames the play window.
 *   - sprites are **event-triggered** (FUN_1000_0724): each @OPENING series
 *     activates at its trigger frame, advances its own sheet frame, holds the
 *     last frame when repeats==0 (the guy holds nframes-5), loops `repeats`
 *     times otherwise. Series 1 (Sun) uses the hand-keyed frame ladder from
 *     FUN_1000_042c; series 8 (logo) shows at frame 767; series -1 ends @891.
 *   - each sprite blits at its **.SS per-frame (x,y)** screen anchor
 *     (bottom-center registration), clipped to the 320x132 play window.
 *   - credit cards (OPENCRD1/2/3) show in their [start,end] windows.
 *
 * Reconstructed (documented residual; needs a DOSBox runtime trace): the exact
 * scroll-position table (0x4f0e) -> the pan here is linear in the frame number;
 * the late Z-order swap at frame 507; the logo palette cross-fade.
 * ============================================================================ */
#ifdef _VICEROY_MODERN
#include <stdio.h>
#include <string.h>
#include "platform.h"

#define INTRO_PLAY_H 132          /* FUN_1000_02e4: play area is 320 x 132 */
#define INTRO_SERIES_SUN   1      /* hand-keyed frame ladder (FUN_1000_042c) */
#define INTRO_SERIES_GUY   7      /* holds at nframes-5                      */
#define INTRO_SERIES_LOGO  8      /* OPENLOGO single frame                   */

typedef struct { int start, end, series, sprite; } intro_credit_t;
typedef struct { int series, frame, repeats, basex; } intro_anim_t;

extern const char *intro_anim_sheet(int series);
extern const char *intro_credit_sheet(int series);
extern int         intro_end_frame(void);

static pik_image_t g_bg;          static int g_have_bg;       /* OPENING.PIK 960x132 */
static pik_image_t g_border;      static int g_have_border;   /* OPENBORD.PIK 320x200 */
static ss_sheet_t  g_anim[10];    static int g_anim_ok[10];
static ss_sheet_t  g_cred[3];     static int g_cred_ok[3];
static const char *g_dir;

int intro_render_open(const char *dir)
{
    char path[512];
    g_dir = dir;
    snprintf(path, sizeof path, "%s/OPENING.PIK", dir);
    g_have_bg = (pik_load(path, &g_bg) == 0);
    if (g_have_bg && g_bg.has_pal) vid_set_palette(g_bg.pal);
    snprintf(path, sizeof path, "%s/OPENBORD.PIK", dir);
    g_have_border = (pik_load(path, &g_border) == 0);
    for (int s = 0; s < 10; s++) {
        const char *n = intro_anim_sheet(s);
        if (!n) continue;
        snprintf(path, sizeof path, "%s/%s", dir, n);
        g_anim_ok[s] = (ss_load(path, &g_anim[s]) == 0);
    }
    for (int s = 0; s < 3; s++) {
        snprintf(path, sizeof path, "%s/%s", dir, intro_credit_sheet(s));
        g_cred_ok[s] = (ss_load(path, &g_cred[s]) == 0);
    }
    /* renderable iff at least the backdrop decoded (sheets are best-effort). */
    return g_have_bg ? 0 : -1;
}

/* window_left(frame): the 320-window's left edge in the 960-wide scene. The
 * scene pans its full width over the run (linear reconstruction; the exact
 * per-step table lives at OPENING.EXE DGROUP 0x4f0e). */
static int window_left(int frame)
{
    int span = g_bg.w - VID_W;
    if (span <= 0) return 0;
    int end = intro_end_frame();
    if (end <= 0) return 0;
    long wl = (long)frame * span / end;
    if (wl < 0) wl = 0;
    if (wl > span) wl = span;
    return (int)wl;
}

/* draw the panning scene window into the play area, framed by OPENBORD. */
static void draw_backdrop(int frame)
{
    uint8_t *fb = vid_framebuffer();
    memset(fb, 0, VID_W * VID_H);
    if (g_have_border) {                       /* base: the border frame */
        int w = g_border.w < VID_W ? g_border.w : VID_W;
        int h = g_border.h < VID_H ? g_border.h : VID_H;
        for (int y = 0; y < h; y++)
            memcpy(fb + y * VID_W, g_border.pixels + y * g_border.w, w);
    }
    if (!g_have_bg) return;
    int wl = window_left(frame);
    int h = g_bg.h < INTRO_PLAY_H ? g_bg.h : INTRO_PLAY_H;   /* top 132 rows */
    int w = g_bg.w - wl < VID_W ? g_bg.w - wl : VID_W;
    for (int y = 0; y < h; y++)
        memcpy(fb + y * VID_W, g_bg.pixels + y * g_bg.w + wl, w);
}

/* Sun frame index (0-based) keyed to the global frame -- FUN_1000_042c. */
static int sun_idx(int frame)
{
    int v = 1;
    if (frame > 0x86) v = 2;  if (frame > 0x98) v = 3;  if (frame > 0xac) v = 4;
    if (frame > 0xc2) v = 5;  if (frame > 0xdb) v = 6;  if (frame > 0xeb) v = 7;
    if (frame > 0xfb) v = 6;
    return v - 1;
}

/* Resolve an @OPENING entry to a sheet-frame index at `frame`, or -1 if the
 * animation is not currently on screen. Closed form of the FUN_1000_0724
 * activate/advance/hold/repeat state machine (works for random-access frames
 * so the keyframe dumps are correct). */
static int anim_frame_index(const intro_anim_t *a, int frame)
{
    int s = a->series;
    if (s < 0 || s >= 10 || !g_anim_ok[s]) return -1;
    int N = g_anim[s].nframes;
    if (N <= 0 || frame < a->frame) return -1;

    if (s == INTRO_SERIES_SUN) {                 /* hand-keyed ladder, holds */
        int idx = sun_idx(frame);
        return idx < N ? idx : N - 1;
    }
    int e = frame - a->frame;                    /* ticks since activation */
    if (a->repeats == 0) {                        /* play once, then hold */
        if (e < N) return e;
        int hold = (s == INTRO_SERIES_GUY && N > 5) ? N - 5 : N - 1;
        return hold;
    }
    /* repeats>0: play `repeats` cycles, then leave the screen */
    long total = (long)N * a->repeats;
    if (e >= total) return -1;
    return e % N;
}

/* blit a sheet frame at its stored (x,y) screen anchor (bottom-center
 * registration), clipped to the play window. */
static void blit_anchored(const ss_sheet_t *sh, int idx, int cy1)
{
    if (idx < 0 || idx >= sh->nframes) return;
    const ss_frame_t *f = &sh->frames[idx];
    int tlx = f->x - (int)f->w / 2;
    int tly = f->y - (int)f->h;
    ss_blit_clip(sh, idx, tlx, tly, 0, 0, VID_W - 1, cy1);
}

void intro_render_frame(int frame, const intro_credit_t *creds, int nc,
                        const intro_anim_t *anims, int na)
{
    draw_backdrop(frame);
    /* event-triggered animation sprites (scene-fixed screen anchors). */
    for (int i = 0; i < na; i++) {
        int s = anims[i].series;
        if (s < 0 || s >= 10 || !g_anim_ok[s]) continue;
        int idx = anim_frame_index(&anims[i], frame);
        if (idx >= 0)
            blit_anchored(&g_anim[s], idx, INTRO_PLAY_H - 1);
    }
    /* credit cards active in their [start,end] window. */
    for (int i = 0; i < nc; i++) {
        if (frame < creds[i].start || frame > creds[i].end) continue;
        int s = creds[i].series;
        if (s < 0 || s >= 3 || !g_cred_ok[s]) continue;
        int spr = creds[i].sprite;
        if (spr < 0 || spr >= g_cred[s].nframes) spr = 0;
        blit_anchored(&g_cred[s], spr, INTRO_PLAY_H - 1);
    }
}

void intro_render_message(const char *msg)
{
    /* the @MESSAGES "Loading Game..." card; drawn via the shell font if present. */
    extern ff_font_t *viceroy_font(void);
    ff_font_t *fnt = viceroy_font();
    draw_backdrop(intro_end_frame());
    if (fnt && msg && msg[0]) {
        int w = ff_text_width(fnt, msg, 1);
        fnt->colors[1] = fnt->colors[2] = fnt->colors[3] = 15;
        ff_draw(fnt, msg, (VID_W - w) / 2, VID_H - 24, 1);
    }
}

void intro_render_close(void)
{
    if (g_have_bg)     { pik_free(&g_bg);     g_have_bg = 0; }
    if (g_have_border) { pik_free(&g_border); g_have_border = 0; }
    for (int s = 0; s < 10; s++) if (g_anim_ok[s]) { ss_free(&g_anim[s]); g_anim_ok[s] = 0; }
    for (int s = 0; s < 3; s++)  if (g_cred_ok[s]) { ss_free(&g_cred[s]); g_cred_ok[s] = 0; }
}

/* present a frame: SDL when live, else dump a numbered PPM for verification. */
void intro_render_present(int frame)
{
    extern int viceroy_interactive(void);
    if (viceroy_interactive()) { vid_present(); return; }
    char path[256];
    snprintf(path, sizeof path, "/tmp/intro_%04d.ppm", frame);
    vid_screenshot_ppm(path);
}

int intro_aborted(void) { return vid_poll_key() == 0x1B; }   /* ESC skips */
#endif /* _VICEROY_MODERN */

/* ##################################################################### */
/* ## SOURCE: viceroy_source/src/platform/pik.c
/* ## range: 0x40000000..
/* ##################################################################### */
/* ============================================================================
 * pik.c -- MADSPACK 2.0 container + FAB decompressor (.PIK backdrop loader)
 * ----------------------------------------------------------------------------
 * Modern platform layer (milestone 3).  COLONIZE's .PIK backdrops are MADS
 * engine pack files (MicroProse shared toolkit -- see docs/ENGINE.md):
 *
 *   container: "MADSPACK 2.0\x1A" pad to 14 | count:u16le | 0xA0-byte item
 *     directory of 10-byte entries { type:u8 (0=stored, 1=FAB), priority:u8,
 *     size:u32le, csize:u32le } | item payloads back-to-back.
 *
 *   FAB stream: "FAB" | shift:u8 (10..13) | bitbuf0:u16le | LZ77 bitstream.
 *     bit 1            -> literal byte
 *     bit 0, bit 0     -> 2-bit extra length (2..5), 1-byte offset (-1..-256)
 *     bit 0, bit 1     -> 2-byte {offset | length}; len==0 -> extension byte
 *                         (0 = end of stream, 1 = continue, n -> length n+1)
 *
 *   .PIK item layout (verified against the COLONIZE files):
 *     item 0: 8-byte header { height:u16le, width:u16le, ... }
 *     item 1: width*height 8bpp pixels
 *     item 2: 768-byte VGA palette (256 x 6-bit RGB)
 *
 * Format facts recovered via the ScummVM MADS engine's reader; this is a
 * fresh C implementation against the COLONIZE data files.
 * ============================================================================ */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "platform.h"

#define RD16(p)  ((uint16_t)((p)[0] | ((p)[1] << 8)))
#define RD32(p)  ((uint32_t)((p)[0] | ((p)[1] << 8) | ((p)[2] << 16) | ((uint32_t)(p)[3] << 24)))

/* ---- FAB LZ77 ------------------------------------------------------------ */
typedef struct {
    const uint8_t *src, *p;
    long           size;
    uint32_t       bitbuf;   /* 17 bits live: (new word << 1) | carry */
    int            bits;
} fab_t;

static int fab_bit(fab_t *f)
{
    if (--f->bits == 0) {
        if (f->p - f->src >= f->size) return -1;
        f->bitbuf = ((uint32_t)RD16(f->p) << 1) | (f->bitbuf & 1);
        f->p += 2;
        f->bits = 16;
    }
    int b = f->bitbuf & 1;
    f->bitbuf >>= 1;
    return b;
}

static int fab_decompress(const uint8_t *src, long srcsize,
                          uint8_t *dst, long dstsize)
{
    if (srcsize < 6 || memcmp(src, "FAB", 3) != 0) return -1;
    int shift = src[3];
    if (shift < 10 || shift > 13) return -1;
    int  ofs_shift = 16 - shift;
    int  ofs_mask  = (0xFF << (shift - 8)) & 0xFF;
    int  len_mask  = (1 << ofs_shift) - 1;

    fab_t f = { src, src + 6, srcsize, RD16(src + 4), 16 };
    long out = 0;

    for (;;) {
        int b = fab_bit(&f);
        if (b < 0) return -1;
        if (b) {                                   /* literal */
            if (out >= dstsize || f.p - src >= srcsize) return -1;
            dst[out++] = *f.p++;
            continue;
        }
        long clen, cofs;
        if ((b = fab_bit(&f)) < 0) return -1;
        if (b == 0) {                              /* short match */
            int b1 = fab_bit(&f), b0 = fab_bit(&f);
            if (b1 < 0 || b0 < 0) return -1;
            clen = ((b1 << 1) | b0) + 2;
            cofs = (long)*f.p++ - 256;
        } else {                                   /* long match */
            cofs = ((((f.p[1] >> ofs_shift) | ofs_mask) << 8) | f.p[0]) - 0x10000;
            clen = f.p[1] & len_mask;
            f.p += 2;
            if (clen == 0) {
                clen = *f.p++;
                if (clen == 0) break;              /* end of stream */
                if (clen == 1) continue;           /* no-op */
                clen++;
            } else {
                clen += 2;
            }
        }
        if (out + cofs < 0) return -1;
        while (clen-- > 0) {
            if (out >= dstsize) return -1;
            dst[out] = dst[out + cofs];
            out++;
        }
    }
    return out == dstsize ? 0 : -1;
}

/* ---- MADSPACK container (shared by .PIK and .FF loaders) ----------------- */
int madspack_load(const char *path, uint8_t **items, uint32_t *sizes, int max)
{
    FILE *fp = fopen(path, "rb");
    if (!fp) return -1;
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    uint8_t *data = malloc(fsize);
    if (!data || fread(data, 1, fsize, fp) != (size_t)fsize) {
        free(data); fclose(fp); return -1;
    }
    fclose(fp);

    if (fsize < 16 + 0xA0 || memcmp(data, "MADSPACK", 8) != 0) {
        free(data); return -1;
    }
    int count = RD16(data + 14);
    const uint8_t *dir = data + 16;
    long off = 16 + 0xA0;
    if (count > max) count = max;

    for (int i = 0; i < count; i++) {
        int      type  = dir[i*10];
        uint32_t size  = RD32(dir + i*10 + 2);
        uint32_t csize = RD32(dir + i*10 + 6);
        items[i] = malloc(size);
        sizes[i] = size;
        int ok = (off + csize <= fsize) && items[i];
        if (ok) {
            if (type == 0)
                memcpy(items[i], data + off, size < csize ? size : csize);
            else
                ok = fab_decompress(data + off, csize, items[i], size) == 0;
        }
        off += csize;
        if (!ok) {
            for (int j = 0; j <= i; j++) free(items[j]);
            free(data); return -1;
        }
    }
    free(data);
    return count;
}

/* ---- .PIK backdrops ------------------------------------------------------ */
int pik_load(const char *path, pik_image_t *img)
{
    memset(img, 0, sizeof *img);

    uint8_t *items[8] = { 0 };
    uint32_t sizes[8] = { 0 };
    int count = madspack_load(path, items, sizes, 8);
    if (count < 2) return -1;

    /* item 0 = dims header, 1 = pixels, 2 = 6-bit VGA palette */
    if (count >= 2 && sizes[0] >= 4) {
        img->h = RD16(items[0]);
        img->w = RD16(items[0] + 2);
    }
    img->pixels = items[1];
    if ((uint32_t)img->w * img->h != sizes[1]) {   /* trust the payload size */
        if (img->w && sizes[1] % img->w == 0) img->h = sizes[1] / img->w;
    }
    if (count >= 3 && sizes[2] >= 768) {
        for (int i = 0; i < 256; i++) {            /* 6-bit -> 8-bit */
            img->pal[i*3+0] = (uint8_t)((items[2][i*3+0] << 2) | (items[2][i*3+0] >> 4));
            img->pal[i*3+1] = (uint8_t)((items[2][i*3+1] << 2) | (items[2][i*3+1] >> 4));
            img->pal[i*3+2] = (uint8_t)((items[2][i*3+2] << 2) | (items[2][i*3+2] >> 4));
        }
        img->has_pal = 1;
    }
    free(items[0]);
    if (count >= 3) free(items[2]);
    return 0;
}

void pik_free(pik_image_t *img)
{
    free(img->pixels);
    img->pixels = 0;
}

/* ##################################################################### */
/* ## SOURCE: viceroy_source/src/platform/script_input.c
/* ## range: 0x40000000..
/* ##################################################################### */
/* ============================================================================
 * script_input.c -- the determinism rig's input half (ROUTE_B_PLAN 0.1).
 * ----------------------------------------------------------------------------
 * Drives the shell from a text script instead of (ahead of) SDL, so the
 * same input sequence is byte-replayable run after run -- headless included
 * (without a script, headless vid_poll_key() returns 0 forever and the
 * shell cannot be driven at all).
 *
 * Script grammar (one directive per line; '#' comments):
 *   key TOKEN     queue one keypress.  TOKEN: ESC RETURN ENTER SPACE TAB
 *                 UP DOWN LEFT RIGHT F1..F12, a single character (b e 1 ...),
 *                 or a raw code 0xNN / decimal.
 *   wait N        N empty polls (lets the shell redraw between keys)
 *   shot PATH     write a PPM screenshot checkpoint (pixdiff input)
 *   seed N        set the MSC LCG seed word (DGROUP:0x28EE) at this point
 *   quit          deliver VID_QUIT_REQUESTED
 *
 * On script exhaustion: headless delivers quit (a finished script means a
 * finished run); with a display, input falls through to SDL.
 *
 * Activation: VICEROY_SCRIPT=path env or --script=path argv (main_modern).
 * Boot-time seeding: VICEROY_SEED=N env or --seed=N (applied before the
 * first poll; `seed` directives override mid-script).
 *
 * SDL2 keysym values are the shell's native vocabulary (KEY_UP=1073741906,
 * F1..F12 = 1073741882..1073741893); tokens map onto those exact codes.
 * ============================================================================ */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "platform.h"

extern unsigned int g_rand_seed_28EE;   /* runtime/rng.c (DGROUP:0x28EE) */
extern int vid_screenshot_ppm(const char *path);

enum ev_kind { EV_KEY, EV_WAIT, EV_SHOT, EV_SEED, EV_QUIT };

struct ev {
    enum ev_kind kind;
    int value;              /* key code / wait count / seed */
    char path[200];         /* shot target */
};

#define MAX_EV 4096
static struct ev q[MAX_EV];
static int q_len = 0, q_pos = 0, q_active = 0;

static const struct { const char *name; int code; } TOKENS[] = {
    {"ESC", 27}, {"RETURN", 13}, {"ENTER", 13}, {"SPACE", 32}, {"TAB", 9},
    {"UP", 1073741906}, {"DOWN", 1073741905},
    {"LEFT", 1073741904}, {"RIGHT", 1073741903},
    {"F1", 1073741882}, {"F2", 1073741883}, {"F3", 1073741884},
    {"F4", 1073741885}, {"F5", 1073741886}, {"F6", 1073741887},
    {"F7", 1073741888}, {"F8", 1073741889}, {"F9", 1073741890},
    {"F10", 1073741891}, {"F11", 1073741892}, {"F12", 1073741893},
};

static int token_code(const char *t)
{
    for (size_t i = 0; i < sizeof TOKENS / sizeof *TOKENS; i++)
        if (!strcmp(t, TOKENS[i].name))
            return TOKENS[i].code;
    if (t[0] && !t[1])
        return (unsigned char)t[0];           /* single character */
    if (!strncmp(t, "0x", 2) || (t[0] >= '0' && t[0] <= '9'))
        return (int)strtol(t, NULL, 0);       /* raw code */
    return -1;
}

int script_input_load(const char *path)
{
    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "script: cannot open '%s'\n", path);
        return -1;
    }
    char line[256];
    int ln = 0;
    q_len = q_pos = 0;
    while (fgets(line, sizeof line, f)) {
        ln++;
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        char *nl = strchr(p, '\n');
        if (nl) *nl = 0;
        char *cr = strchr(p, '\r');
        if (cr) *cr = 0;
        if (!*p || *p == '#')
            continue;
        if (q_len >= MAX_EV) {
            fprintf(stderr, "script:%d: too many events (max %d)\n", ln, MAX_EV);
            fclose(f);
            return -1;
        }
        struct ev *e = &q[q_len];
        char tok[200];
        if (sscanf(p, "key %199s", tok) == 1) {
            int c = token_code(tok);
            if (c < 0) {
                fprintf(stderr, "script:%d: unknown key token '%s'\n", ln, tok);
                fclose(f);
                return -1;
            }
            e->kind = EV_KEY; e->value = c;
        } else if (sscanf(p, "wait %d", &e->value) == 1) {
            e->kind = EV_WAIT;
        } else if (sscanf(p, "shot %199s", e->path) == 1) {
            e->kind = EV_SHOT;
        } else if (sscanf(p, "seed %i", &e->value) == 1) {
            e->kind = EV_SEED;
        } else if (!strcmp(p, "quit")) {
            e->kind = EV_QUIT;
        } else {
            fprintf(stderr, "script:%d: bad directive '%s'\n", ln, p);
            fclose(f);
            return -1;
        }
        q_len++;
    }
    fclose(f);
    q_active = 1;
    fprintf(stderr, "script: %d events from '%s'\n", q_len, path);
    return 0;
}

int script_input_active(void) { return q_active && q_pos < q_len; }

/* one poll: returns the key to deliver (0 = no key this poll).
 * side-effect directives (shot/seed) run inline until a key/wait/quit. */
int script_input_poll(int headless)
{
    while (q_active && q_pos < q_len) {
        struct ev *e = &q[q_pos];
        switch (e->kind) {
        case EV_KEY:
            q_pos++;
            return e->value;
        case EV_WAIT:
            if (e->value > 0) { e->value--; return 0; }
            q_pos++;
            continue;
        case EV_SHOT:
            q_pos++;
            if (vid_screenshot_ppm(e->path) == 0)
                fprintf(stderr, "script: shot -> %s\n", e->path);
            else
                fprintf(stderr, "script: shot FAILED -> %s\n", e->path);
            continue;
        case EV_SEED:
            q_pos++;
            g_rand_seed_28EE = (unsigned int)e->value;
            fprintf(stderr, "script: seed = 0x%08X\n", (unsigned)e->value);
            continue;
        case EV_QUIT:
            q_pos++;
            return VID_QUIT_REQUESTED;
        }
    }
    if (q_active && headless)
        return VID_QUIT_REQUESTED;   /* finished script = finished run */
    return 0;
}

